// Read a window of rows of one band from a BSQ ENVI cube.
export async function readRows(file, header, band, y0, rows) {
  const rowBytes = header.samples * header.bytesPerSample;
  const bandBytes = rowBytes * header.lines;
  const out = new Uint8Array(rowBytes * rows);
  for (let r = 0; r < rows; r += 1) {
    const start = header.offset + band * bandBytes + (y0 + r) * rowBytes;
    const bytes = await file.slice(start, start + rowBytes).arrayBuffer();
    out.set(new Uint8Array(bytes), r * rowBytes);
  }
  return out;
}
